#!/usr/bin/env node
import { resolve } from "node:path";
import { captureSession, formatCaptureReport } from "./capture.js";
import { formatInitResult, initBundle } from "./init.js";
import { formatIndexResult, indexBundle } from "./index-cmd.js";
import { formatInspectReport, inspectFile } from "./inspect.js";
import { formatPackResult, packBundle } from "./pack.js";
import { getSpecInfo } from "./spec.js";
import {
  exitCodeFor,
  formatValidationReport,
  validateBundle,
} from "./validate.js";

export async function main(argv: string[] = process.argv.slice(2)): Promise<number> {
  if (argv.includes("--spec-info")) {
    const info = getSpecInfo();
    if (argv.includes("--json")) {
      console.log(JSON.stringify(info, null, 2));
    } else {
      console.log(
        [
          `${info.name} ${info.version}`,
          `OKF spec: ${info.specVersion}`,
          `Pinned SHA: ${info.specSha}`,
          `Spec URL: ${info.specUrl}`,
        ].join("\n"),
      );
    }
    return 0;
  }

  if (argv.length === 0 || argv[0] === "--help" || argv[0] === "-h") {
    printHelp();
    return 0;
  }

  if (argv[0] === "--version" || argv[0] === "-V") {
    const info = getSpecInfo();
    console.log(`${info.name} ${info.version}`);
    return 0;
  }

  const [command, ...rest] = argv;

  try {
    switch (command) {
      case "validate":
        return await cmdValidate(rest);
      case "init":
        return await cmdInit(rest);
      case "index":
        return await cmdIndex(rest);
      case "pack":
        return await cmdPack(rest);
      case "inspect":
        return await cmdInspect(rest);
      case "capture":
        return await cmdCapture(rest);
      case "help":
        printHelp();
        return 0;
      default:
        console.error(`Unknown command: ${command}`);
        printHelp();
        return 1;
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    console.error(`pi-okf: ${message}`);
    return 1;
  }
}

async function cmdValidate(args: string[]): Promise<number> {
  const flags = parseFlags(args);
  const bundlePath = flags.positional[0];
  if (!bundlePath) {
    console.error("Usage: pi-okf validate <bundle-path> [--strict] [--json] [--fail-on-warnings]");
    return 1;
  }

  const options = {
    strict: flags.bool.has("strict"),
    failOnWarnings: flags.bool.has("fail-on-warnings"),
  };
  const report = await validateBundle(resolve(bundlePath), options);
  console.log(formatValidationReport(report, flags.bool.has("json")));
  return exitCodeFor(report, options);
}

async function cmdInit(args: string[]): Promise<number> {
  const flags = parseFlags(args);
  const name = flags.positional[0];
  if (!name) {
    console.error("Usage: pi-okf init <bundle-name> [--dir <path>]");
    return 1;
  }
  const dir = flags.opts.get("dir");
  const result = await initBundle({ name, dir });
  console.log(formatInitResult(result));
  return 0;
}

async function cmdIndex(args: string[]): Promise<number> {
  const flags = parseFlags(args);
  const bundlePath = flags.positional[0];
  if (!bundlePath) {
    console.error("Usage: pi-okf index <bundle-path> [--write]");
    return 1;
  }
  const write = flags.bool.has("write");
  const result = await indexBundle(resolve(bundlePath), { write });
  console.log(formatIndexResult(result, write));
  return 0;
}

async function cmdPack(args: string[]): Promise<number> {
  const flags = parseFlags(args);
  const bundlePath = flags.positional[0];
  if (!bundlePath) {
    console.error("Usage: pi-okf pack <bundle-path> [--out <path>] [--no-okf]");
    return 1;
  }
  const result = await packBundle(resolve(bundlePath), {
    out: flags.opts.get("out"),
    noOkf: flags.bool.has("no-okf"),
  });
  console.log(formatPackResult(result));
  return 0;
}

async function cmdInspect(args: string[]): Promise<number> {
  const flags = parseFlags(args);
  const filePath = flags.positional[0];
  if (!filePath) {
    console.error("Usage: pi-okf inspect <file.md> [--json]");
    return 1;
  }
  const report = await inspectFile(resolve(filePath));
  console.log(formatInspectReport(report, flags.bool.has("json")));
  return report.parseError ? 1 : 0;
}

async function cmdCapture(args: string[]): Promise<number> {
  const flags = parseFlags(args);
  const bundlePath = flags.positional[0];
  if (!bundlePath) {
    console.error(
      "Usage: pi-okf capture <bundle-path> --summary <text> [--title <text>] [--decision <text>...] [--change <text>...] [--question <text>...]",
    );
    return 1;
  }
  const summary = flags.opts.get("summary");
  if (!summary) {
    console.error("pi-okf capture: --summary is required.");
    return 1;
  }

  const picksFromLists = (...keys: string[]): string[] => {
    for (const key of keys) {
      const values = flags.lists.get(key);
      if (values && values.length > 0) return values;
    }
    return [];
  };

  const report = await captureSession(resolve(bundlePath), {
    title: flags.opts.get("title"),
    summary,
    decisions: picksFromLists("decision", "decisions"),
    changes: picksFromLists("change", "changes"),
    questions: picksFromLists("question", "questions"),
  });
  console.log(formatCaptureReport(report));
  // Capture itself succeeded if no write error was thrown; downstream
  // validation warnings are informational, not a failure of the capture.
  return report.validation.errors.length > 0 ? 1 : 0;
}

function parseFlags(args: string[]): {
  positional: string[];
  bool: Set<string>;
  opts: Map<string, string>;
  lists: Map<string, string[]>;
} {
  const positional: string[] = [];
  const bool = new Set<string>();
  const opts = new Map<string, string>();
  const lists = new Map<string, string[]>();

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === "--") {
      positional.push(...args.slice(i + 1));
      break;
    }
    if (arg.startsWith("--")) {
      const body = arg.slice(2);
      if (body.includes("=")) {
        const eq = body.indexOf("=");
        const k = body.slice(0, eq);
        const v = body.slice(eq + 1);
        if (LIST_OPTION_NAMES.has(k)) {
          appendList(lists, k, v);
        } else {
          opts.set(k, v);
        }
        continue;
      }
      const next = args[i + 1];
      if (next && !next.startsWith("-")) {
        // option with value for known value-taking flags
        if (LIST_OPTION_NAMES.has(body)) {
          appendList(lists, body, next);
          i += 1;
          continue;
        }
        if (body === "dir" || body === "out" || body === "title" || body === "summary") {
          opts.set(body, next);
          i += 1;
          continue;
        }
      }
      bool.add(body);
      continue;
    }
    if (arg.startsWith("-") && arg.length === 2) {
      bool.add(arg.slice(1));
      continue;
    }
    positional.push(arg);
  }

  return { positional, bool, opts, lists };
}

function appendList(lists: Map<string, string[]>, key: string, value: string): void {
  const existing = lists.get(key) ?? [];
  existing.push(value);
  lists.set(key, existing);
}

const LIST_OPTION_NAMES = new Set([
  "decision",
  "decisions",
  "change",
  "changes",
  "question",
  "questions",
]);

function printHelp(): void {
  const info = getSpecInfo();
  console.log(`pi-okf ${info.version} — Open Knowledge Format (OKF) CLI

Usage:
  pi-okf validate <bundle-path> [--strict] [--json] [--fail-on-warnings]
  pi-okf init <bundle-name> [--dir <path>]
  pi-okf index <bundle-path> [--write]
  pi-okf pack <bundle-path> [--out <path>] [--no-okf]
  pi-okf inspect <file.md> [--json]
  pi-okf capture <bundle-path> --summary <text> [--title <text>] [--decision <text>...] [--change <text>...] [--question <text>...]
  pi-okf --spec-info [--json]
  pi-okf --help | --version

Exit codes (validate):
  0  clean (no errors or warnings)
  1  hard error (missing/invalid frontmatter, reserved-file structure, Attested Computation runtime, or missing bundle)
  2  soft warnings only (recommended metadata, broken links, legacy v0.1 fields)

Spec: ${info.specUrl} (v${info.specVersion})
`);
}

const isDirect =
  process.argv[1] &&
  (process.argv[1].endsWith("cli.ts") ||
    process.argv[1].endsWith("cli.js") ||
    process.argv[1].endsWith("pi-okf") ||
    process.argv[1].endsWith("pi-okf.js"));

if (isDirect) {
  main().then(
    (code) => {
      process.exitCode = code;
    },
    (err) => {
      console.error(err);
      process.exitCode = 1;
    },
  );
}
